from test_player_exceptions import test,tests

test('Profiles tab preserves character-specific buff preferences', "local buffs=BuffTap.db.buffs; local keys=BuffTap.db.keys; BuffTap:Options(); assert(#BuffTap.options.pages==9 and BuffTap.options.tabs[8].text=='Profiles'); assert(BuffTap.db.buffs==buffs and BuffTap.db.keys==keys)")
test('First migration keeps old preferences and a rollback backup', "BuffTapDB={keys={'CTRL-G'},size=91,opacity=.7,buffs={thorns=false},seconds=75}; BuffTap:InitDB(); assert(BuffTap.db.size==91 and BuffTap.db.keys[1]=='CTRL-G' and BuffTap.db.opacity==.7 and BuffTap.db.seconds==75 and not BuffTap.db.buffs.thorns); assert(rawget(BuffTapDB,'size')==nil and BuffTapDB.profileMigrationBackup.size==91)")
test('Migrated profile choice survives repeat InitDB', "local name=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.size=88; for i=1,4 do BuffTap:InitDB() end; assert(name==BuffTap.profileDB:GetCurrentProfile() and BuffTap.db.size==88)")
test('New default profile changes general preferences only', "BuffTap.db.buffs.thorns=false; BuffTap.db.priorities.motw=6; BuffTap.db.group=true; BuffTap.db.size=100; assert(BuffTap:CreateSettingsProfile('Raid',false)); assert(BuffTap.db.size==64 and BuffTap.db.buffs.thorns==false and BuffTap.db.priorities.motw==6 and BuffTap.db.group)")
test('Switch immediately clears old bindings and arms new binding', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.keys={'CTRL-G'}; assert(BuffTap:CreateSettingsProfile('Other',false)); assert(bindings.MOUSEWHEELDOWN and not bindings['CTRL-G']); assert(BuffTap:SelectSettingsProfile(old)); assert(bindings['CTRL-G'] and not bindings.MOUSEWHEELDOWN)")
test('Copy current preferences deep copies shared tables', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.keys={'ALT-B'}; BuffTap.db.minimap.minimapPos=120; assert(BuffTap:CreateSettingsProfile('Clone',true)); BuffTap.db.keys[1]='CTRL-B'; BuffTap.db.minimap.minimapPos=220; assert(BuffTap.profileDB.sv.profiles[old].keys[1]=='ALT-B' and BuffTap.profileDB.sv.profiles[old].minimap.minimapPos==120)")
test('Copy shared profile never changes buffs by default', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.size=80; BuffTap:CreateSettingsProfile('Copy',false); BuffTap.db.buffs.thorns=false; BuffTap.db.weaponSeconds=90; assert(BuffTap:CopySettingsProfile(old)); assert(BuffTap.db.size==80 and not BuffTap.db.buffs.thorns and BuffTap.db.weaponSeconds==90)")
test('Same-class optional import includes buff setup but not session state', "local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.buffs.thorns=false; BuffTap.db.priorities.motw=7; BuffTap.blessingPlayers={temporary={choice='bow'}}; BuffTap:CreateSettingsProfile('Destination',true); BuffTap.db.buffs.thorns=true; BuffTap.db.priorities.motw=1; assert(BuffTap:CopySettingsProfile(source,BuffTap.profileDB.keys.char)); assert(not BuffTap.db.buffs.thorns and BuffTap.db.priorities.motw==7); assert(BuffTap.blessingPlayers.temporary.choice=='bow')")
test('Cross-class import rejects entire operation before changing shared preferences', "local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.size=99; BuffTap:CreateSettingsProfile('Dest',false); BuffTap.profileDB.global.characterSetups[source].Foreign={class='PALADIN',profile=source,settings={buffs={thorns=false}}}; assert(not BuffTap:CopySettingsProfile(source,'Foreign')); assert(BuffTap.db.size==64 and BuffTap.db.buffs.thorns~=false)")
test('Wrong source profile cannot import character settings', "BuffTap:CreateSettingsProfile('Source',false); BuffTap:CreateSettingsProfile('Dest',false); BuffTap.profileDB.global.characterSetups.Source.Wrong={class='DRUID',profile='Not Source',settings={}}; assert(not BuffTap:CopySettingsProfile('Source','Wrong'))")
test('Foreign class option is hidden in copy UI', "BuffTap:CreateSettingsProfile('Foreign',false); BuffTap:CreateSettingsProfile('Dest',false); BuffTap.profileDB.global.characterSetups.Foreign={Foreign={class='PALADIN',profile='Foreign',settings={}}}; BuffTap:Options(); local p=BuffTap.options.profiles; p.sourceName='Foreign'; BuffTap:Options(); assert(not p.includeClass.shown and not p.character.shown)")
test('Same-class copy UI reveals recipient only after explicit opt-in', "local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',false); BuffTap:Options(); local p=BuffTap.options.profiles; p.sourceName=source; BuffTap:Options(); assert(p.includeClass.shown and not p.character.shown); p.includeClass:SetChecked(true); p.includeClass.scripts.OnClick(p.includeClass); assert(p.character.shown and p.classSource)")
test('Rename carries all character mappings and source metadata', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.profileDB.sv.profileKeys.Alt=old; BuffTap:SaveClassSetup(); assert(BuffTap:RenameSettingsProfile('Shared')); assert(BuffTap.profileDB:GetCurrentProfile()=='Shared' and BuffTap.profileDB.sv.profileKeys.Alt=='Shared' and not BuffTap.profileDB.sv.profiles[old]); assert(BuffTap.profileDB.global.characterSetups.Shared[BuffTap.profileDB.keys.char].profile=='Shared')")
test('Only unused inactive profiles can be deleted', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.profileDB.sv.profileKeys.Alt=old; BuffTap:CreateSettingsProfile('Active',false); assert(not BuffTap:DeleteSettingsProfile(old) and not BuffTap:DeleteSettingsProfile('Active')); BuffTap.profileDB.sv.profileKeys.Alt=nil; assert(BuffTap:DeleteSettingsProfile(old))")
test('Reset profile does not reset class setup', "BuffTap.db.size=110; BuffTap.db.group=true; BuffTap.db.buffs.thorns=false; BuffTap.db.keys={'CTRL-G'}; assert(BuffTap:ResetSettingsProfile()); assert(BuffTap.db.size==64 and BuffTap.db.keys[1]=='MOUSEWHEELDOWN' and not BuffTap.db.buffs.thorns and BuffTap.db.group)")
test('Reset all detaches this character without resetting shared profile', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.size=100; BuffTap.profileDB.sv.profileKeys.Alt=old; assert(BuffTap:ResetCharacterSettings()); assert(BuffTap.profileDB:GetCurrentProfile()~=old and BuffTap.db.size==64 and BuffTap.profileDB.sv.profiles[old].size==100 and BuffTap.profileDB.sv.profileKeys.Alt==old)")
test('Combat blocks every profile mutation', "local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Other',true); combat=true; assert(not BuffTap:SelectSettingsProfile(old) and not BuffTap:CreateSettingsProfile('No',true) and not BuffTap:CopySettingsProfile(old) and not BuffTap:RenameSettingsProfile('No') and not BuffTap:ResetSettingsProfile() and not BuffTap:DeleteSettingsProfile(old) and not BuffTap:ResetCharacterSettings()); assert(BuffTap.profileDB:GetCurrentProfile()=='Other' and not BuffTap.profileDB.sv.profiles.No)")
test('Invalid and duplicate names do not create profiles', "local old=BuffTap.profileDB:GetCurrentProfile(); for _,v in ipairs({'','   ','|Tfake:0|t',string.rep('x',51),'bad'..string.char(1)}) do assert(not BuffTap:CreateSettingsProfile(v,true) and not BuffTap:RenameSettingsProfile(v)) end; assert(not BuffTap:CreateSettingsProfile(old,true)); assert(BuffTap:CreateSettingsProfile('  Trimmed  ',true) and BuffTap.profileDB:GetCurrentProfile()=='Trimmed')")
test('Profile reset and copy require confirmation in options', "BuffTap:Options(); local p=BuffTap.options.profiles; BuffTap.db.size=90; p.reset.scripts.OnClick(); assert(p.confirm.shown and BuffTap.db.size==90); p.accept.scripts.OnClick(); assert(not p.confirm.shown and BuffTap.db.size==64)")
test('Switching profiles preserves existing group-session exceptions', "BuffTap.blessingPlayers={test={choice='bow'}}; BuffTap:CreateSettingsProfile('Other',true); assert(BuffTap.blessingPlayers.test.choice=='bow')")
test('Malformed imported class preferences run through existing normalization', "local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',false); BuffTap.profileDB.global.characterSetups[source].Broken={class='DRUID',profile=source,settings={buffs='bad',priorities={motw='bad'},weaponChoices={main='not-valid'},raidGroups='bad'}}; assert(BuffTap:CopySettingsProfile(source,'Broken')); assert(type(BuffTap.db.buffs)=='table' and not BuffTap.db.priorities.motw and not next(BuffTap.db.weaponChoices) and #BuffTap.db.raidGroups==8)")
for loc in ('deDE','frFR','esES','ptBR'):
 test('Profiles controls and confirmation localized '+loc,"BuffTap:Options(); assert(BuffTap.options.tabs[8].text~='Profiles'); local p=BuffTap.options.profiles; p.reset.scripts.OnClick(); assert(p.confirmText.text~=\"Reset this profile's shared preferences? Buff and class settings will stay unchanged.\")",locale=loc)
test('Unreadable class identity cannot enable or execute class imports', "local source=BuffTap.profileDB:GetCurrentProfile(); BuffTap:CreateSettingsProfile('Dest',false); BuffTap.profileDB.global.characterSetups[source].Unknown={profile=source,settings={}}; UnitClass=function() return nil,nil end; assert(#BuffTap:ClassCopySources(source)==0 and not BuffTap:CopySettingsProfile(source,'Unknown'))")
test('AceDB shutdown saves class preferences before storage cleanup, even in combat', "BuffTap.db.buffs.thorns=false; combat=true; local db=LibStub('AceDB-3.0'); db.frame.scripts.OnEvent(db.frame,'PLAYER_LOGOUT'); local p=BuffTap.profileDB; assert(not p.sv.global.characterSetups[p:GetCurrentProfile()][p.keys.char].settings.buffs.thorns)")
test('Profiles page fits existing panel and tabs fit header', """
local original=CreateFrame
CreateFrame=function(...) local f=original(...); f.SetSize=function(self,w,h) self.width=w; self.height=h end; f.SetPoint=function(self,...) self.point={...} end; return f end
BuffTap:Options(); local p=BuffTap.options.profiles
for _,c in ipairs({p.active,p.name,p.create,p.source,p.copy,p.character,p.rename,p.reset,p.deletePick,p.delete,p.confirm}) do assert(c.point[2]+c.width<=724 and -c.point[3]+c.height<=624) end
local last=BuffTap.options.tabs[9]; assert(last.point[2]+last.width<=736)
""")
print('ALL',len(tests),'SCENARIOS PASSED')
